      "సందేశాలు యూరోపియన్ యూనియన్‌లో భద్రపరచబడతాయి, పాల్గొనేవారికి మాత్రమే కనిపిస్తాయి, 90 రోజుల తర్వాత తొలగించబడతాయి.",
      "మీ ఇమెయిల్ ఇతర సభ్యులకు ఎప్పుడూ చూపబడదు, అమ్మబడదు.",
      "అనువదించిన కాల్: మీ వాక్యాలు ప్రత్యక్షంగా పంపబడతాయి, రికార్డ్ చేయబడవు.",
      "మైక్ మరియు కెమెరా: మీ బ్రౌజర్ అనుమతి అడుగుతుంది, దాన్ని మీరు ఎప్పుడైనా వెనక్కి తీసుకోవచ్చు.",
      "మీ ప్రొఫైల్ నుండి మీ ఖాతాను ఎప్పుడైనా తొలగించవచ్చు.",
      "తెలుసుకోవడం మంచిది: అనువదించాల్సిన వాక్యాలు MyMemory సేవ ద్వారా వెళ్తాయి, అది వాటిని భద్రపరచవచ్చు. సున్నితమైన సమాచారాన్ని అనువదించకండి. ఏ భద్రతా సంపూర్ణం కాదు.",
