      "Ìtumọ̀ aládàáṣe: dídára rẹ̀ yàtọ̀ láti èdè sí èdè. Àwọn èdè tí a ń sọ jù lọ ni ó ṣeé gbẹ́kẹ̀lé jù lọ.",
